CREATE TABLE IF NOT EXISTS runtime_controls(id text PRIMARY KEY,workspace_id text NOT NULL REFERENCES workspaces(id),task_id text NOT NULL,action text NOT NULL,payload jsonb NOT NULL,state text NOT NULL DEFAULT 'pending',created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(workspace_id,task_id) REFERENCES tasks(workspace_id,id));
CREATE TABLE IF NOT EXISTS model_checks(workspace_id text NOT NULL REFERENCES workspaces(id),request_id text NOT NULL,model text NOT NULL,state text NOT NULL DEFAULT 'reserved',reserved_tokens integer NOT NULL DEFAULT 64,input_tokens integer,output_tokens integer,result jsonb,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,request_id));
